<script>
'use strict';
const cv  = document.getElementById('sky');
const ctx = cv.getContext('2d');
const TAU = Math.PI * 2;
const tsv = document.getElementById('tsv'), yrv = document.getElementById('yrv'), pch = document.getElementById('pch');

let W = 0, H = 0, DPR = 1, Rsys = 0, sc = 1, sunR = 30;
let farLayer = null, nearLayer = null, twinklers = [], vignette = null, topShade = null, botShade = null;

/* ---------------- ephemeris ---------------- */
const K = 0.127;                                  // angular-speed constant, Kepler-compressed
const omega = f => K / Math.pow(f, 1.15);
const PLANETS = [
  {name:'MERCURY', frac:.165, size:2.7,  hi:'#d3c7b2', md:'#8a7f6c', lo:'#332e26', data:'0.39 AU · 88 D'},
  {name:'VENUS',   frac:.245, size:4.4,  hi:'#f2dcaa', md:'#c2a165', lo:'#46351d', data:'0.72 AU · 225 D'},
  {name:'EARTH',   frac:.335, size:4.7,  hi:'#93c2ea', md:'#3f6a99', lo:'#0e1e34', data:'1.00 AU · 365 D', moon:true},
  {name:'MARS',    frac:.430, size:3.5,  hi:'#e28e5e', md:'#a34a2a', lo:'#33170c', data:'1.52 AU · 687 D'},
  {name:'JUPITER', frac:.665, size:11.5, hi:'#e8caa0', md:'#a97f52', lo:'#332413', data:'5.20 AU · 11.9 Y', bands:true},
  {name:'SATURN',  frac:.795, size:9.2,  hi:'#eed9a6', md:'#b39a62', lo:'#3d3319', data:'9.58 AU · 29.4 Y', rings:true},
  {name:'URANUS',  frac:.885, size:6.5,  hi:'#bce7ea', md:'#63a7ad', lo:'#16333a', data:'19.2 AU · 84 Y',  uring:true},
  {name:'NEPTUNE', frac:.965, size:6.3,  hi:'#8fa9e6', md:'#3f5da8', lo:'#101a38', data:'30.1 AU · 165 Y'},
];
PLANETS.forEach(p => {
  p.phase = Math.random() * TAU;
  p.omega = omega(p.frac);
  p.trail = Math.min(.85, Math.max(.16, p.omega * .55));
});
const YEAR_RATE = omega(0.335) / TAU;

/* asteroid belt */
const BELT = [];
for (let i = 0; i < 270; i++) {
  const f  = 0.505 + Math.random() * 0.085;
  const al = (0.14 + Math.random() * 0.4).toFixed(2);
  const w  = Math.random();
  const col = w < 0.6 ? `rgba(198,188,168,${al})` : w < 0.85 ? `rgba(160,150,140,${al})` : `rgba(214,196,170,${al})`;
  BELT.push({ f, a: Math.random() * TAU, w: omega(f) * (0.85 + Math.random() * 0.3), s: 0.5 + Math.random() * 0.9, col });
}
BELT.sort((a, b) => a.col < b.col ? -1 : 1);      // group fill styles → fewer state changes

/* comet on an eccentric ellipse, sun at focus */
const COMET = { e: 0.77, aFrac: 0.565, peri: 2.25, E: 0.55, n: TAU / 75, x: 0, y: 0, vx: 0, vy: 0, rFrac: 1, str: 0 };
function cometPos(E) {
  const a = COMET.aFrac * Rsys, b = a * Math.sqrt(1 - COMET.e * COMET.e);
  const x = a * (Math.cos(E) - COMET.e), y = b * Math.sin(E);
  const cw = Math.cos(COMET.peri), sw = Math.sin(COMET.peri);
  return { x: x * cw - y * sw, y: x * sw + y * cw };
}
const PARTS = [];
let emitAcc = 0;

/* ---------------- state ---------------- */
let simT = 0, ts = 1, paused = false, years = 0;
if (matchMedia('(prefers-reduced-motion: reduce)').matches) ts = 0.2;
let mx = -1e4, my = -1e4, parX = 0, parY = 0, tParX = 0, tParY = 0;
let hover = null, curHover = false;

/* ---------------- starfield ---------------- */
function milkyway(g, w, h) {
  g.save(); g.translate(w / 2, h / 2); g.rotate(-0.5);
  const bw = Math.max(w, h) * 0.95, bh = Math.min(w, h) * 0.42;
  const gr = g.createLinearGradient(0, -bh / 2, 0, bh / 2);
  gr.addColorStop(0,   'rgba(170,195,255,0)');
  gr.addColorStop(0.42,'rgba(165,190,245,0.055)');
  gr.addColorStop(0.5, 'rgba(226,206,236,0.075)');
  gr.addColorStop(0.58,'rgba(165,190,245,0.05)');
  gr.addColorStop(1,   'rgba(170,195,255,0)');
  g.fillStyle = gr; g.fillRect(-bw / 2, -bh / 2, bw, bh);
  g.fillStyle = '#cfd8ee';
  for (let i = 0; i < 420; i++) {
    const off = (Math.random() + Math.random() + Math.random() - 1.5) / 1.5 * bh * 0.5;
    g.globalAlpha = 0.05 + Math.random() * 0.22;
    g.fillRect((Math.random() - 0.5) * bw, off, 0.7, 0.7);
  }
  const nb = g.createRadialGradient(bw * 0.18, -bh * 0.05, 0, bw * 0.18, -bh * 0.05, 120);
  nb.addColorStop(0, 'rgba(255,196,150,0.05)'); nb.addColorStop(1, 'rgba(255,196,150,0)');
  g.globalAlpha = 1; g.fillStyle = nb; g.fillRect(bw * 0.18 - 120, -bh * 0.05 - 120, 240, 240);
  g.restore();
}
function makeLayer(density, maxR, pad, milky) {
  const w = W + pad * 2, h = H + pad * 2;
  const c = document.createElement('canvas');
  c.width = w * DPR; c.height = h * DPR;
  const g = c.getContext('2d'); g.scale(DPR, DPR);
  if (milky) milkyway(g, w, h);
  const cols = ['#ffffff', '#dfe8ff', '#fff3d8', '#ffdcb4'];
  const n = Math.round(w * h / density);
  for (let i = 0; i < n; i++) {
    const x = Math.random() * w, y = Math.random() * h;
    const r = 0.3 + Math.pow(Math.random(), 2.6) * maxR;
    const a = 0.15 + Math.random() * 0.75;
    g.globalAlpha = a; g.fillStyle = cols[(Math.random() * 4) | 0];
    g.beginPath(); g.arc(x, y, r, 0, TAU); g.fill();
    if (Math.random() > 0.986) {                      // diffraction glint on the brightest few
      g.globalAlpha = a * 0.35; g.strokeStyle = '#dfe8ff'; g.lineWidth = 0.6;
      const L = 4 + r * 4;
      g.beginPath(); g.moveTo(x - L, y); g.lineTo(x + L, y); g.moveTo(x, y - L); g.lineTo(x, y + L); g.stroke();
    }
  }
  return { c, pad };
}
function resize() {
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  W = window.innerWidth; H = window.innerHeight;
  cv.width = W * DPR; cv.height = H * DPR;
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  const m = Math.min(W, H);
  Rsys = m / 2 - 26;
  sc = Math.min(1.5, Math.max(0.72, m / 820));
  sunR = Math.min(54, Math.max(22, m * 0.058));
  farLayer  = makeLayer(2400, 1.1, 30, true);
  nearLayer = makeLayer(5200, 1.9, 30, false);
  twinklers = [];
  for (let i = 0; i < 70; i++) twinklers.push({
    x: Math.random() * W, y: Math.random() * H, r: 0.5 + Math.random() * 1.1,
    ph: Math.random() * TAU, sp: 0.4 + Math.random() * 1.4, f: 0.55 + Math.random() * 0.3
  });
  vignette = ctx.createRadialGradient(W/2, H/2, m * 0.35, W/2, H/2, Math.hypot(W, H) * 0.62);
  vignette.addColorStop(0, 'rgba(2,4,9,0)'); vignette.addColorStop(1, 'rgba(2,4,9,0.6)');
  topShade = ctx.createLinearGradient(0, 0, 0, 110);
  topShade.addColorStop(0, 'rgba(3,5,10,0.55)'); topShade.addColorStop(1, 'rgba(3,5,10,0)');
  botShade = ctx.createLinearGradient(0, H - 90, 0, H);
  botShade.addColorStop(0, 'rgba(3,5,10,0)'); botShade.addColorStop(1, 'rgba(3,5,10,0.45)');
}

/* ---------------- simulation step ---------------- */
function step(dt) {
  const sdt = paused ? 0 : dt * ts;
  simT += sdt;
  years += sdt * YEAR_RATE;

  for (const p of PLANETS) {
    p.ang = p.phase + simT * p.omega;
    p.x = Math.cos(p.ang) * p.frac * Rsys;
    p.y = Math.sin(p.ang) * p.frac * Rsys;
    p.s = p.size * sc;
  }

  /* comet — Kepler's second law: dE/dt = n / (1 − e·cosE) */
  const px0 = COMET.x, py0 = COMET.y;
  COMET.E += COMET.n / (1 - COMET.e * Math.cos(COMET.E)) * sdt;
  if (COMET.E >= TAU) COMET.E -= TAU;
  const c = cometPos(COMET.E);
  if (sdt > 0) { COMET.vx = (c.x - px0) / sdt; COMET.vy = (c.y - py0) / sdt; }
  COMET.x = c.x; COMET.y = c.y;
  const cr = Math.hypot(c.x, c.y) || 1;
  COMET.rFrac = cr / Rsys;
  const fade = Math.max(0, Math.min(1, (1.15 - COMET.rFrac) / 0.5));
  COMET.str = Math.min(2.2, Math.pow(0.5 / Math.max(COMET.rFrac, 0.06), 2)) * fade;

  /* twin tails: ion (anti-sunward, cold blue) + dust (lagging, warm) */
  const ax = c.x / cr, ay = c.y / cr;
  emitAcc += sdt * 95 * COMET.str;
  let guard = 0;
  while (emitAcc >= 1 && guard++ < 8) {
    emitAcc -= 1;
    const jx = (Math.random() - 0.5) * 2.5, jy = (Math.random() - 0.5) * 2.5;
    if (Math.random() < 0.55) {
      const sp = (34 + Math.random() * 48) * (0.55 + 0.45 * Math.min(COMET.str, 1.4));
      const L = 0.8 + Math.random() * 0.8;
      PARTS.push({ x: c.x + jx, y: c.y + jy,
        vx: ax * sp + COMET.vx * 0.06 + (Math.random() - 0.5) * 7,
        vy: ay * sp + COMET.vy * 0.06 + (Math.random() - 0.5) * 7,
        life: L, life0: L, s: 0.6 + Math.random() * 0.9, c: '152,200,255' });
    } else {
      const vl = Math.hypot(COMET.vx, COMET.vy) || 1;
      const dx = ax - COMET.vx / vl * 0.55, dy = ay - COMET.vy / vl * 0.55;
      const dl = Math.hypot(dx, dy) || 1;
      const sp = (14 + Math.random() * 20) * (0.55 + 0.45 * Math.min(COMET.str, 1.4));
      const L = 1.5 + Math.random() * 1.2;
      PARTS.push({ x: c.x + jx, y: c.y + jy,
        vx: dx / dl * sp + COMET.vx * 0.22, vy: dy / dl * sp + COMET.vy * 0.22,
        life: L, life0: L, s: 0.9 + Math.random() * 1.5, c: '255,213,156' });
    }
  }
  if (emitAcc > 4) emitAcc = 4;
  if (PARTS.length > 430) PARTS.splice(0, PARTS.length - 430);
  const damp = Math.exp(-0.55 * sdt);
  for (let i = PARTS.length - 1; i >= 0; i--) {
    const p = PARTS[i];
    p.life -= sdt;
    if (p.life <= 0) { PARTS.splice(i, 1); continue; }
    p.x += p.vx * sdt; p.y += p.vy * sdt; p.vx *= damp; p.vy *= damp;
  }

  /* hover hit-test in screen space */
  const ox = W / 2 + parX, oy = H / 2 + parY;
  const bodies = [{ x: ox, y: oy, r: sunR, name: 'SOL', data: 'G2V · 5778 K' }];
  for (const p of PLANETS) bodies.push({ x: ox + p.x, y: oy + p.y, r: p.s, name: p.name, data: p.data });
  bodies.push({ x: ox + COMET.x, y: oy + COMET.y, r: 3, name: 'COMET C/2025 K1', data: 'e 0.77 · q 0.13 R' });
  hover = null; let best = 1e9;
  for (const b of bodies) {
    const d = Math.hypot(mx - b.x, my - b.y);
    if (d < Math.max(b.r + 6, 10) && d < best) { best = d; hover = b; }
  }
  if (curHover !== !!hover) { curHover = !!hover; cv.style.cursor = hover ? 'pointer' : 'crosshair'; }
}

/* ---------------- rendering ---------------- */
function drawSun(t) {
  const R = sunR * (1 + 0.025 * Math.sin(t * 1.3) + 0.014 * Math.sin(t * 2.9 + 1.7));
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 2; i++) {                       // slow rotating coronal rays
    ctx.save(); ctx.rotate(t * 0.05 + i * Math.PI); ctx.scale(1, 0.26);
    const fg = ctx.createRadialGradient(0, 0, R * 0.3, 0, 0, R * 3.4);
    fg.addColorStop(0, 'rgba(255,176,84,0.14)'); fg.addColorStop(1, 'rgba(255,140,60,0)');
    ctx.fillStyle = fg; ctx.beginPath(); ctx.arc(0, 0, R * 3.4, 0, TAU); ctx.fill();
    ctx.restore();
  }
  let g = ctx.createRadialGradient(0, 0, R * 0.5, 0, 0, R * 5.4);
  g.addColorStop(0, 'rgba(255,158,64,0.30)'); g.addColorStop(0.3, 'rgba(255,120,44,0.12)'); g.addColorStop(1, 'rgba(255,100,40,0)');
  ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, 0, R * 5.4, 0, TAU); ctx.fill();
  g = ctx.createRadialGradient(0, 0, R * 0.7, 0, 0, R * 1.9);
  g.addColorStop(0, 'rgba(255,196,110,0.5)'); g.addColorStop(0.55, 'rgba(255,140,56,0.16)'); g.addColorStop(1, 'rgba(255,120,50,0)');
  ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, 0, R * 1.9, 0, TAU); ctx.fill();
  ctx.restore();
  g = ctx.createRadialGradient(-R * 0.22, -R * 0.28, R * 0.05, 0, 0, R);
  g.addColorStop(0, '#fff9ea'); g.addColorStop(0.5, '#ffe3a1'); g.addColorStop(0.82, '#ffab48'); g.addColorStop(1, '#f57a26');
  ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, 0, R, 0, TAU); ctx.fill();
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  g = ctx.createRadialGradient(0, 0, R * 0.85, 0, 0, R * 1.28);
  g.addColorStop(0, 'rgba(255,170,80,0.55)'); g.addColorStop(1, 'rgba(255,140,60,0)');
  ctx.fillStyle = g; ctx.beginPath(); ctx.arc(0, 0, R * 1.28, 0, TAU); ctx.fill();
  ctx.restore();
}

function ringHalf(x, y, r, back) {
  const tilt = -0.5, sq = 0.42, mul = back ? 0.72 : 1;
  const rings = [[1.45, r * 0.34, 0.5], [1.82, r * 0.16, 0.34], [2.02, r * 0.08, 0.2]];
  for (const [f, w, al] of rings) {
    ctx.strokeStyle = `rgba(216,198,152,${(al * mul).toFixed(3)})`;
    ctx.lineWidth = w;
    ctx.beginPath();
    ctx.ellipse(x, y, r * f, r * f * sq, tilt, back ? Math.PI : 0, back ? TAU : Math.PI);
    ctx.stroke();
  }
}

function drawPlanet(p) {
  const r = p.s, x = p.x, y = p.y;
  const sa = Math.atan2(y, x);                        // direction from the sun to this planet
  if (p.rings) ringHalf(x, y, r, true);
  if (p.uring) {
    ctx.strokeStyle = 'rgba(190,225,230,0.14)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.ellipse(x, y, r * 1.9, r * 0.55, 1.25, Math.PI, TAU); ctx.stroke();
  }
  const lx = x - Math.cos(sa) * r * 0.5, ly = y - Math.sin(sa) * r * 0.5;
  const g = ctx.createRadialGradient(lx, ly, r * 0.1, x, y, r * 1.02);
  g.addColorStop(0, p.hi); g.addColorStop(0.55, p.md); g.addColorStop(1, p.lo);
  ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
  const nx = x + Math.cos(sa) * r * 0.75, ny = y + Math.sin(sa) * r * 0.75;
  const g2 = ctx.createRadialGradient(nx, ny, r * 0.1, nx, ny, r * 1.35);
  g2.addColorStop(0, 'rgba(3,5,10,0.55)'); g2.addColorStop(0.55, 'rgba(3,5,10,0.28)'); g2.addColorStop(1, 'rgba(3,5,10,0)');
  ctx.fillStyle = g2; ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
  if (p.bands) {                                      // Jupiter: cloud belts + Great Red Spot
    ctx.save(); ctx.beginPath(); ctx.arc(x, y, r - 0.3, 0, TAU); ctx.clip(); ctx.translate(x, y);
    const bands = [[-0.55,0.16,'rgba(255,244,224,0.14)'],[-0.28,0.12,'rgba(88,58,34,0.20)'],
                   [-0.02,0.15,'rgba(255,240,218,0.12)'],[0.22,0.11,'rgba(96,62,36,0.20)'],
                   [0.45,0.13,'rgba(255,240,218,0.10)'],[0.68,0.12,'rgba(80,52,30,0.18)']];
    for (const [o, h, c] of bands) { ctx.fillStyle = c; ctx.fillRect(-r, o * r, 2 * r, h * r); }
    ctx.fillStyle = 'rgba(196,88,56,0.8)';
    ctx.beginPath(); ctx.ellipse(r * 0.32, r * 0.30, r * 0.16, r * 0.09, -0.2, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(230,150,110,0.5)';
    ctx.beginPath(); ctx.ellipse(r * 0.32, r * 0.285, r * 0.09, r * 0.045, -0.2, 0, TAU); ctx.fill();
    ctx.restore();
  }
  if (p.uring) {
    ctx.strokeStyle = 'rgba(190,225,230,0.2)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.ellipse(x, y, r * 1.9, r * 0.55, 1.25, 0, Math.PI); ctx.stroke();
  }
  if (p.rings) ringHalf(x, y, r, false);
  if (p.moon) {
    const ma = simT * 3.1 + 1, md = r + 7.5 * sc, mr = Math.max(1.4, 2 * sc);
    const mxx = x + Math.cos(ma) * md, myy = y + Math.sin(ma) * md;
    const mg = ctx.createRadialGradient(mxx - Math.cos(sa) * mr * 0.6, myy - Math.sin(sa) * mr * 0.6, 0.3, mxx, myy, mr * 1.1);
    mg.addColorStop(0, '#d8dce4'); mg.addColorStop(1, '#3a3f4c');
    ctx.fillStyle = mg; ctx.beginPath(); ctx.arc(mxx, myy, mr, 0, TAU); ctx.fill();
  }
}

function drawComet() {
  ctx.save(); ctx.globalCompositeOperation = 'lighter';
  const glow = 0.35 + 0.65 * Math.min(COMET.str * 1.2, 1);
  for (const p of PARTS) {
    const lf = p.life / p.life0;
    ctx.globalAlpha = Math.min(0.55, lf * 0.55 * glow);
    ctx.fillStyle = `rgb(${p.c})`;
    ctx.beginPath(); ctx.arc(p.x, p.y, p.s * (0.5 + 0.6 * lf), 0, TAU); ctx.fill();
  }
  ctx.globalAlpha = 1;
  const cr = (4 + 9 * Math.min(COMET.str, 1.6)) * sc + 3;
  const cg = ctx.createRadialGradient(COMET.x, COMET.y, 0, COMET.x, COMET.y, cr);
  cg.addColorStop(0, 'rgba(210,235,255,0.75)'); cg.addColorStop(0.4, 'rgba(160,200,255,0.22)'); cg.addColorStop(1, 'rgba(150,190,255,0)');
  ctx.fillStyle = cg; ctx.beginPath(); ctx.arc(COMET.x, COMET.y, cr, 0, TAU); ctx.fill();
  if (COMET.str > 0.15) {
    ctx.globalAlpha = Math.min(0.5, COMET.str * 0.25);
    ctx.strokeStyle = '#cfe4ff'; ctx.lineWidth = 0.7;
    const L = 6 + 10 * Math.min(COMET.str, 2);
    ctx.beginPath(); ctx.moveTo(COMET.x - L, COMET.y); ctx.lineTo(COMET.x + L, COMET.y);
    ctx.moveTo(COMET.x, COMET.y - L); ctx.lineTo(COMET.x, COMET.y + L); ctx.stroke();
  }
  ctx.restore();
  ctx.fillStyle = '#eef6ff';
  ctx.beginPath(); ctx.arc(COMET.x, COMET.y, 1.5, 0, TAU); ctx.fill();
}

function drawHover() {
  if (!hover) return;
  const { x, y, r } = hover;
  ctx.strokeStyle = 'rgba(232,238,252,0.55)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.arc(x, y, r + 5, 0, TAU); ctx.stroke();
  const right = x < W - 180, dir = right ? 1 : -1;
  const ex  = x + dir * (r + 5) * 0.72, ey  = y - (r + 5) * 0.72;
  const ex2 = ex + dir * 12,            ey2 = ey - 12;
  ctx.strokeStyle = 'rgba(232,238,252,0.4)';
  ctx.beginPath(); ctx.moveTo(ex, ey); ctx.lineTo(ex2, ey2); ctx.lineTo(ex2 + dir * 6, ey2); ctx.stroke();
  ctx.textBaseline = 'alphabetic';
  ctx.textAlign = right ? 'left' : 'right';
  const tx = ex2 + dir * 10;
  ctx.letterSpacing = '1.5px';
  ctx.font = '10px Menlo, Consolas, "Liberation Mono", monospace';
  ctx.fillStyle = '#eef2fa';
  ctx.fillText(hover.name, tx, ey2 - 3);
  ctx.letterSpacing = '0.5px';
  ctx.font = '9px Menlo, Consolas, "Liberation Mono", monospace';
  ctx.fillStyle = '#8d99b3';
  ctx.fillText(hover.data, tx, ey2 + 9);
  ctx.letterSpacing = '0px';
  ctx.textAlign = 'left';
}

function draw(t) {
  ctx.fillStyle = '#04060b'; ctx.fillRect(0, 0, W, H);
  const amb = ctx.createRadialGradient(W/2, H/2, 0, W/2, H/2, Math.max(W, H) * 0.7);
  amb.addColorStop(0, 'rgba(26,32,52,0.5)'); amb.addColorStop(1, 'rgba(26,32,52,0)');
  ctx.fillStyle = amb; ctx.fillRect(0, 0, W, H);

  ctx.drawImage(farLayer.c,  -farLayer.pad + parX * 0.22, -farLayer.pad + parY * 0.22, W + farLayer.pad * 2,  H + farLayer.pad * 2);
  ctx.drawImage(nearLayer.c, -nearLayer.pad + parX * 0.5,  -nearLayer.pad + parY * 0.5,  W + nearLayer.pad * 2, H + nearLayer.pad * 2);
  for (const s of twinklers) {
    ctx.globalAlpha = 0.18 + 0.6 * (0.5 + 0.5 * Math.sin(t * s.sp + s.ph));
    ctx.fillStyle = '#e8eefc';
    ctx.beginPath(); ctx.arc(s.x + parX * s.f, s.y + parY * s.f, s.r, 0, TAU); ctx.fill();
  }
  ctx.globalAlpha = 1;

  ctx.save();
  ctx.translate(W / 2 + parX, H / 2 + parY);

  /* comet orbit hint */
  ctx.strokeStyle = 'rgba(150,170,215,0.10)'; ctx.lineWidth = 1; ctx.setLineDash([2, 7]);
  ctx.beginPath();
  for (let i = 0; i <= 90; i++) {
    const q = cometPos(i / 90 * TAU);
    i ? ctx.lineTo(q.x, q.y) : ctx.moveTo(q.x, q.y);
  }
  ctx.stroke(); ctx.setLineDash([]);

  /* orbit paths */
  for (const p of PLANETS) {
    ctx.strokeStyle = hover && hover.name === p.name ? 'rgba(190,208,244,0.32)' : 'rgba(150,172,215,0.10)';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(0, 0, p.frac * Rsys, 0, TAU); ctx.stroke();
  }

  /* asteroid belt */
  let lastCol = '';
  for (const a of BELT) {
    const ang = a.a + simT * a.w, rr = a.f * Rsys;
    if (a.col !== lastCol) { ctx.fillStyle = a.col; lastCol = a.col; }
    ctx.fillRect(Math.cos(ang) * rr, Math.sin(ang) * rr, a.s, a.s);
  }

  /* motion trails, tapering behind each planet */
  ctx.lineCap = 'round';
  for (const p of PLANETS) {
    const n = 20, base = hover && hover.name === p.name ? 0.5 : 0.3;
    for (let k = 0; k < n; k++) {
      ctx.globalAlpha = base * Math.pow(1 - k / n, 1.6);
      ctx.strokeStyle = p.hi;
      ctx.lineWidth = (1 - k / n) * 2.2 * sc + 0.3;
      ctx.beginPath();
      ctx.arc(0, 0, p.frac * Rsys, p.ang - p.trail * (k + 1) / n, p.ang - p.trail * k / n);
      ctx.stroke();
    }
  }
  ctx.globalAlpha = 1; ctx.lineCap = 'butt';

  drawSun(t);
  for (const p of PLANETS) drawPlanet(p);
  drawComet();

  ctx.restore();

  drawHover();

  ctx.fillStyle = vignette; ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = topShade; ctx.fillRect(0, 0, W, 110);
  ctx.fillStyle = botShade; ctx.fillRect(0, H - 90, W, 90);
}

/* ---------------- input ---------------- */
